package com.localdownload.mobile;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;
import java.util.*;

public class MainActivity extends Activity {
    static final int BLUE=Color.rgb(36,107,253),TEXT=Color.rgb(23,34,56),MUTED=Color.rgb(99,114,136),BG=Color.rgb(244,247,252);
    private EditText link;private CheckBox session;private Button download;private LinearLayout history;private TextView progressTitle,progressDetail;private ProgressBar bar;private Button stop;
    private final Handler handler=new Handler(Looper.getMainLooper());private String lastHistory="";private boolean active=false;
    private final Runnable ticker=new Runnable(){@Override public void run(){if(!active)return;renderProgress();renderHistory();handler.postDelayed(this,600);}};
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String value,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(value);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
    Button button(String value,boolean primary){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:BLUE);b.setTextSize(14);b.setBackground(shape(primary?BLUE:Color.rgb(234,240,254),12));b.setMinHeight(dp(48));b.setPadding(dp(12),dp(6),dp(12),dp(6));return b;}
    LinearLayout card(){LinearLayout c=column();c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(shape(Color.WHITE,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(14),0,0);c.setLayoutParams(p);return c;}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);LinearLayout root=column();root.setPadding(dp(20),dp(24),dp(20),dp(28));scroll.addView(root);setContentView(scroll);
        root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(20),Math.max(dp(24),insets.getSystemWindowInsetTop()+dp(12)),dp(20),Math.max(dp(28),insets.getSystemWindowInsetBottom()+dp(16)));return insets;});
        root.addView(text("↓  LocalSaver",29,TEXT,true));TextView intro=text("Keep the videos you want to watch again.",14,MUTED,false);intro.setPadding(0,dp(8),0,dp(10));root.addView(intro);
        LinearLayout platforms=new LinearLayout(this);platforms.setOrientation(LinearLayout.HORIZONTAL);String[] labels={"Facebook","Instagram","YouTube"};String[] addresses={"https://m.facebook.com/","https://www.instagram.com/","https://m.youtube.com/"};
        for(int i=0;i<labels.length;i++){final String address=addresses[i];Button b=button(labels[i],false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);if(i>0)p.setMargins(dp(7),0,0,0);platforms.addView(b,p);b.setOnClickListener(v->browse(address));}root.addView(platforms);
        LinearLayout input=card();input.addView(text("Save a video",21,TEXT,true));TextView hint=text("Share → LocalSaver from your social app, or paste its link here.",13,MUTED,false);hint.setPadding(0,dp(8),0,dp(12));input.addView(hint);
        link=new EditText(this);link.setSingleLine(true);link.setHint("Paste a video or reel link");link.setTextSize(14);link.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);link.setPadding(dp(12),dp(9),dp(12),dp(9));link.setBackground(shape(BG,12));input.addView(link,new LinearLayout.LayoutParams(-1,dp(52)));
        LinearLayout actions=new LinearLayout(this);Button paste=button("Paste link",false);Button browser=button("Open browser",false);LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,dp(44),1);half.setMargins(0,dp(10),dp(5),0);actions.addView(paste,half);LinearLayout.LayoutParams other=new LinearLayout.LayoutParams(0,dp(44),1);other.setMargins(dp(5),dp(10),0,0);actions.addView(browser,other);input.addView(actions);
        paste.setOnClickListener(v->{ClipboardManager manager=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(manager.hasPrimaryClip()&&manager.getPrimaryClip().getItemCount()>0){String url=Links.extract(String.valueOf(manager.getPrimaryClip().getItemAt(0).coerceToText(this)));if(url.isEmpty())toast("No video link found in the clipboard.");else link.setText(url);}else toast("Copy a video link first.");});
        browser.setOnClickListener(v->{String url=Links.extract(link.getText().toString());if(url.isEmpty())toast("Paste a link first, or choose a site above.");else browse(url);});
        session=new CheckBox(this);session.setText("Use in-app signed-in session");session.setTextSize(13);session.setTextColor(TEXT);session.setChecked(getSharedPreferences("settings",0).getBoolean("session",false));session.setOnCheckedChangeListener((b,checked)->getSharedPreferences("settings",0).edit().putBoolean("session",checked).apply());input.addView(session);
        TextView note=text("For login-required videos, sign in once using Open browser. Your social app's login is separate.",12,MUTED,false);note.setPadding(dp(4),0,0,dp(12));input.addView(note);
        download=button("↓  Download video",true);input.addView(download,new LinearLayout.LayoutParams(-1,dp(52)));download.setOnClickListener(v->startDownload());root.addView(input);
        LinearLayout progress=card();progressTitle=text("Ready when you are",17,TEXT,true);progress.addView(progressTitle);bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(8));bp.setMargins(0,dp(14),0,dp(10));progress.addView(bar,bp);progressDetail=text("MP4 videos are saved to Movies / LocalSaver.",13,MUTED,false);progress.addView(progressDetail);stop=button("Cancel download",false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(44));sp.setMargins(0,dp(12),0,0);progress.addView(stop,sp);stop.setVisibility(View.GONE);stop.setOnClickListener(v->startService(new Intent(this,DownloadService.class).setAction("cancel")));root.addView(progress);
        TextView title=text("Your downloads",22,TEXT,true);title.setPadding(0,dp(24),0,dp(2));root.addView(title);history=column();root.addView(history);
        TextView footer=text("Personal downloads • No ads • Runs on your phone\nWebsite support varies. Protected streams aren't supported.",12,MUTED,false);footer.setPadding(dp(3),dp(22),dp(3),0);root.addView(footer);
        if(saved!=null)link.setText(saved.getString("link",""));handleIntent(getIntent());
    }
    private void handleIntent(Intent intent){if(intent==null)return;String shared=null;if(Intent.ACTION_SEND.equals(intent.getAction()))shared=intent.getStringExtra(Intent.EXTRA_TEXT);else shared=intent.getStringExtra("url");String url=Links.extract(shared);if(!url.isEmpty()){link.setText(url);toast("Link ready. Tap Download video.");}intent.removeExtra(Intent.EXTRA_TEXT);intent.removeExtra("url");}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);handleIntent(intent);}
    @Override protected void onSaveInstanceState(Bundle out){out.putString("link",link.getText().toString());super.onSaveInstanceState(out);}
    @Override protected void onStart(){super.onStart();active=true;ticker.run();}
    @Override protected void onStop(){active=false;handler.removeCallbacks(ticker);super.onStop();}
    private void startDownload(){String url=Links.extract(link.getText().toString());if(url.isEmpty()){toast("Paste or share a video link first.");return;}if(Links.facebookStory(url)){browse(url);toast("Play the story, then tap Download this video in the browser.");return;}
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},33);return;}begin(url,url);}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==33){String url=Links.extract(link.getText().toString());if(!url.isEmpty())begin(url,url);}}
    private void begin(String url,String source){try{DownloadService.begin(this,url,source,session.isChecked());renderProgress();}catch(Exception error){new AlertDialog.Builder(this).setTitle("Cannot download").setMessage(error.getMessage()).setPositiveButton("OK",null).show();}}
    private void browse(String url){startActivity(new Intent(this,BrowserActivity.class).putExtra("url",url));}
    private void renderProgress(){Store.Job job=DownloadService.current;download.setEnabled(!DownloadService.busy);stop.setVisibility(DownloadService.busy?View.VISIBLE:View.GONE);if(job==null)return;progressTitle.setText(job.state.equals("Complete")?"✓  Video saved":job.state);bar.setIndeterminate(DownloadService.busy&&job.progress==0);bar.setProgress((int)job.progress);progressDetail.setText(job.state.equals("Error")?job.error:job.state.equals("Complete")?job.title+"\nMovies / LocalSaver":job.state.equals("Stopped")?job.error:job.title+"\n"+(int)job.progress+"%");}
    private void renderHistory(){List<Store.Job> entries=Store.history(this);Store.Job live=DownloadService.current;for(int i=0;i<entries.size();i++)if(live!=null&&entries.get(i).id.equals(live.id))entries.set(i,live);StringBuilder key=new StringBuilder().append(DownloadService.busy);for(Store.Job j:entries)key.append(j.id).append(j.state).append(j.uri);if(key.toString().equals(lastHistory))return;lastHistory=key.toString();history.removeAllViews();
        if(entries.isEmpty()){TextView empty=text("Your saved videos will appear here. Share a link to get started.",14,MUTED,false);empty.setPadding(dp(3),dp(18),dp(3),0);history.addView(empty);return;}
        for(Store.Job job:entries){LinearLayout row=card();row.setPadding(dp(15),dp(14),dp(15),dp(14));row.addView(text(job.title,15,TEXT,true));TextView detail=text(job.site+" • "+job.state+(job.bytes>0?" • "+String.format(Locale.US,"%.1f MB",job.bytes/1048576d):""),12,MUTED,false);detail.setPadding(0,dp(7),0,dp(8));row.addView(detail);LinearLayout controls=new LinearLayout(this);
            Button open=button("Play",false),again=button("Redownload",false),more=button("•••",false);open.setEnabled(!job.uri.isEmpty());controls.addView(open,new LinearLayout.LayoutParams(0,dp(42),1));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,dp(42),1.3f);ap.setMargins(dp(6),0,dp(6),0);controls.addView(again,ap);controls.addView(more,new LinearLayout.LayoutParams(dp(48),dp(42)));row.addView(controls);history.addView(row);
            open.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(job.uri),"video/mp4").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception error){toast("The video is missing or no video player is available. Try Redownload.");}});
            again.setEnabled(!DownloadService.busy);again.setOnClickListener(v->{String source=job.source.isEmpty()?job.url:job.source;link.setText(source);if(Links.facebookStory(source))browse(source);else begin(source,source);});
            more.setOnClickListener(v->{PopupMenu menu=new PopupMenu(this,more);menu.getMenu().add("Share video");menu.getMenu().add("Open source");menu.getMenu().add("Remove from history");menu.setOnMenuItemClickListener(item->{switch(item.getTitle().toString()){case "Share video":if(!job.uri.isEmpty())try{startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,Uri.parse(job.uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share video"));}catch(Exception e){toast("Video unavailable.");}break;case "Open source":browse(job.source.isEmpty()?job.url:job.source);break;default:Store.remove(this,job.id);lastHistory="";renderHistory();}return true;});menu.show();});
        }
    }
    private void toast(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
}
